window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-32801\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεφροντισμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 2483 na letra π · nº geral 32801</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com cuidado; com atenção; com prudência. 〈φροντίζω〉</p></section></article>\n<article id=\"entry-dgp-32802\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεφύασι</h1><div class=\"entry-meta\"><span>DGP · ordem 2484 na letra π · nº geral 32802</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. perf. ép. de φύω.</p></section></article>\n<article id=\"entry-dgp-32803\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέφυγμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2485 na letra π · nº geral 32803</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">perf. pas., πεφύζοντες part. pl. perf. at. ép., de φεύγω.</p></section></article>\n<article id=\"entry-dgp-32804\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέφυκα</h1><div class=\"entry-meta\"><span>DGP · ordem 2486 na letra π · nº geral 32804</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. φύω.</p></section></article>\n<article id=\"entry-dgp-32805\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεφυκότως</h1><div class=\"entry-meta\"><span>DGP · ordem 2487 na letra π · nº geral 32805</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo natural; naturalmente. 〈φύω〉</p></section></article>\n<article id=\"entry-dgp-32806\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεφυλαγμένως</h1><div class=\"entry-meta\"><span>DGP · ordem 2488 na letra π · nº geral 32806</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com precaução; com cautela. 〈φυ­λάσσω〉</p></section></article>\n<article id=\"entry-dgp-32807\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πεφυῶτας</h1><div class=\"entry-meta\"><span>DGP · ordem 2489 na letra π · nº geral 32807</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. pl. part. pf. ép. de φύω.</p></section></article>\n<article id=\"entry-dgp-32808\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πέψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2490 na letra π · nº geral 32808</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cozimento 2 maturação de frutos 3 fermentação do vinho 4 Medic. maturação dos humores 5 cura de um machucado 6 digestão. 〈πέσσω〉</p></section></article>\n<article id=\"entry-dgp-32809\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῇ,</h1><div class=\"entry-meta\"><span>DGP · ordem 2491 na letra π · nº geral 32809</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. κῇ adv. inter. 1 (lugar) por que caminho? por onde? onde? em direção a qual lugar?: πῇ δή; onde então? πῇ ποτε; onde por acaso? 2 (lugar) em que parte (de um lugar, gen.)?: πῇ γῆς; her. em qual lugar da terra? 3 (modo) como? de que maneira? πῇ δή; como então? πῇ δὴ οὖν ποτε; πῇ μάλιστα; como exatamente? 4 (finalidade) em vista de quê? por quê?</p></section></article>\n<article id=\"entry-dgp-32810\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῄ,</h1><div class=\"entry-meta\"><span>DGP · ordem 2492 na letra π · nº geral 32810</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. κῄ adv. indef. enclít. 1 (lugar) em algum lugar; em alguma parte: οὔτ’ ἐπὶ ἔργα πάρος γ’ ἴμεν οὔτε πῂ ἄλλῃ hom. não iremos nem a nosso trabalho nem a outro lugar 2 (modo) de alguma maneira; de uma maneira qualquer: οὕτω πῃ hom., οὕτω κῃ her. aproximadamente assim, οὕτω πῇ τόδε γ’ ἐστί hom. as coisas estão de algum modo assim, τῇδέ πῃ plat. mais ou menos assim, οὐδέ πῃ ἔστι hom. isso não é possível de maneira alguma, πῂ ἄλλῃ xen. de alguma outra maneira, εἴ πῃ plat. se de alguma maneira, ou se às vezes, se por acaso, μή πῃ plat. de medo que por acaso, μάλιστά κῃ her. aproximadamente, cerca de ♦ em correl., πῂ μέν… πὴ δέ 3 em alguns pontos…, em outros… 4 em parte…, em parte; tanto…, quanto.</p></section></article>\n<article id=\"entry-dgp-32811\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηγαῖος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 2493 na letra π · nº geral 32811</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e, poét., ος, ον de fonte; que escoa de uma nascente ou de uma fonte. 〈πηγή〉</p></section></article>\n<article id=\"entry-dgp-32812\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήγανον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2494 na letra π · nº geral 32812</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ruta; arruda, arbusto. 〈πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-32813\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πήγασος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2495 na letra π · nº geral 32813</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pégaso, cavalo alado de Perseu.</p></section></article>\n<article id=\"entry-dgp-32814\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηγεσίμαλλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2496 na letra π · nº geral 32814</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de tosão espesso. 〈πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-32815\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηγή, ῆς,</h1><div class=\"entry-meta\"><span>DGP · ordem 2497 na letra π · nº geral 32815</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. παγά, ᾶς (ἡ) 1 sing. ou pl. fonte; manancial; nascente: πηγαὶ Σκαμάνδρου hom. nascente do Escamandro, πυρὸς παγαί pínd. manancial do fogo 2 água corrente; fluxo; correnteza: πηγαὶ ποταμῶν hom. a correnteza dos rios, πόντου πηγαῖς eur. as águas do mar, πηγαὶ κλαυμάτων ésql. πηγαὶ δακρύων sóf. rios de lágrimas, πηγαὶ τροφῆς τῷ γεννωμένῳ plat. rios de alimento (de leite) para a criança 3 fonte; princípio; origem: πηγαὶ ἡλίου ésql. mananciais do sol, i.e., o nascente, αἱ τέχναι, ἃς πηγάς φασι τῶν καλῶν εἶναι xen. as artes, que dizem serem a origem das coisas belas, π. τοῦ φρονεῖν plat. fonte da sabedoria, παγὰ ἐπέων pínd. fonte dos cantos. 〈πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-32816\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῆγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2498 na letra π · nº geral 32816</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 peça bem fixada ou bem ajustada 2 compromisso; juramento 3 vigamento; madeiramento (de navio) 4 arcabouço (do esqueleto) 5 matéria congelada; coágulo.</p></section></article>\n<article id=\"entry-dgp-32817\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήγνυμι</h1><div class=\"entry-meta\"><span>DGP · ordem 2499 na letra π · nº geral 32817</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐπήγνυν, fut. πήξω, aor. ἔπηξα dór. ἔπαξα; pas. πήγνυμαι, impf. ἐπηγνύμην, fut.2 παγήσομαι, aor.2 ἐπάγην, aor.1 ἐπήχθην, perf. πέπηγμαι) 1 fixar algo, ac., enterrando em, dat.,ἐν ou ἐπί e dat., διά e gen.; fincar: ἔπαξε διὰ φρενῶν ξίφος pínd. fincou a espada no peito, π. ἐρετμὸν γαίῃ ou ἐν γαίῃ hom. fincar um remo na terra 2 fincar no solo; enfiar na terra algo, ac.: π. σκῆπτρον sóf. fincar no solo um cetro 3 fixar; empalar; espetar algo, ac., em, ἀνά e dat., ἐπί e ac.: κεφαλὴν δέ ἑ θυμὸς ἄνωγε πῆξαι ἀνὰ σκολόπεσσι hom. o coração o impelia a espetar a cabeça nas estacas, κρᾶτα πήξασ’ ἐπ’ ἄκρον θύρσον eur. tendo fincado a cabeça na ponta do tirso 4 fixar algo, ac., em; fixar (os olhos): κατὰ χθονὸς ὄμματα πήξας hom., ἐπὶ χθονὸς ὄμματα πήξας teócr. fixando os olhos sobre o solo, π. σκηνὰς κατ’ ἀγοράν plat. fixar tendas na ágora, π. σταύρωμα tuc. fixar uma paliçada 5 ajustar; construir (navio) 6 fixar tornando compacto; fazer coagular; fazer coalhar (leite); congelar (água); fazer gelar: βορρᾶς πηγνὺς τοὺς ἀνθρώπους xen. o vento do norte fazendo gelar os homens ♦ (perf.2 πέπηγα e m.-q.-perf. ἐπεπήγειν) 7 fincar-se em; ser fincado, ἐν e dat.: πέπηγε δ’ ἐν γῇ sóf. [a lança] foi fincada na terra 8 ter os olhos fixos em algo, πρός ou εἰς e ac. 9 ter por fim, por alvo, inf.: ἡ σοφία ἀρέσκειν πέπηγε plat. a sua sabedoria não tem por fim ser agradável [à alma] 10 estar congelado, gelado 11 (articulação) estar tenso ♦ méd. 12 fixar algo de si, ac., em, dat.: π. χείλεα ἐν ἀλλήλοις a.p. fixar os lábios um no outro, i.e., beijar-se, ἐν φρασὶ π. pínd. fixar bem em seu pensamento 13 juntar ou construir para si (tenda, carro, navio) 14 fazer coagular para si: π. τυρούς luc. preparar queijos ♦ pas. 15 ser fixado; ser plantado: ὅρος παγήσεται tuc. um marco será plantado 16 ser transpassado 17 (leite) coalhar 18 (sal) solidificar-se; cristalizar-se 19 (água) gelar; gelificar 20 (articulações) endurecer; tensionar 21 (pessoa) ficar gélido, imóvel de estupor 22 (juramento, pacto) ser fixado solidamente; tornar-se firme, consistente; ser confirmado: ὅρκος παγείς eur. juramento confirmado solenemente.</p></section></article>\n<article id=\"entry-dgp-32818\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηγνύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2500 na letra π · nº geral 32818</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) = πήγνυμι.</p></section></article>\n<article id=\"entry-dgp-32819\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηγός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2501 na letra π · nº geral 32819</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 compacto; espesso 2 sólido; forte 3 impetuoso (cavalo) 4 enorme (onda) 5 branco; grisalho (cabelo). 〈πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-32820\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηγυλίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2502 na letra π · nº geral 32820</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 glacial ♦ ἡ πηγυλίς 2 gelo 3 pl. flocos de neve.</p></section></article>\n<article id=\"entry-dgp-32821\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηδάλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2503 na letra π · nº geral 32821</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 leme; timão 2 vara ou travessa de madeira, no freio do cavalo 3 pata traseira do gafanhoto 4 Bot. grama; capim. 〈πηδόν〉</p></section></article>\n<article id=\"entry-dgp-32822\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηδάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2504 na letra π · nº geral 32822</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐπήδων, fut. πηδήσομαι, post. πηδήσω, aor. ἐπήδησα, perf. πεπήδηκα; perf. pas. πεπήδημαι, m.-q.-perf. ἐπεπηδήμην) 1 saltar; pular sobre, ac. ou εἰς e ac.: εἰς σκάφη π. sóf. pular sobre os barcos, π. πεδία sóf. saltar pelas planícies, πεδᾶν πήδημα eur. dar um salto, π. μείζονα sóf. dar os maiores saltos 2 (coração) pular; bater forte; palpitar 3 agitar-se; mudar de opinião repentinamente 4 exaltar-se; inflamar-se.</p></section></article>\n<article id=\"entry-dgp-32823\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήδημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2505 na letra π · nº geral 32823</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pulo; salto 2 batimento (do coração); pulsação; palpitação. 〈πηδάω〉</p></section></article>\n<article id=\"entry-dgp-32824\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήδησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2506 na letra π · nº geral 32824</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de pular; salto 2 batimento (do coração); pulsação. 〈πηδάω〉</p></section></article>\n<article id=\"entry-dgp-32825\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηδητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2507 na letra π · nº geral 32825</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que pula; que é bom saltador. 〈πηδάω〉</p></section></article>\n<article id=\"entry-dgp-32826\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηδόν, οῦ (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2508 na letra π · nº geral 32826</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">a parte chata do remo; remo.</p></section></article>\n<article id=\"entry-dgp-32827\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηκτίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2509 na letra π · nº geral 32827</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">instrumento de corda; harpa ou lira. 〈πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-32828\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηκτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2510 na letra π · nº geral 32828</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">I fincado; plantado; cravado 2 fixado; estabelecido 3 formado de partes solidamente unidas ou ajustadas; conexo 4 que pode tornar-se sólido; solidificado; endurecido 5 engrossado; coagulado; coalhado 6 congelado ♦ ἡ πηκτή 7 rede de caça 8 queijo 9 espécie de consólida, planta ♦ τὰ πηκτά 10 batente de porta; porta. 〈πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-32829\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῆλαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2511 na letra π · nº geral 32829</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. de πάλλω.</p></section></article>\n<article id=\"entry-dgp-32830\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηλείδης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 2512 na letra π · nº geral 32830</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) Pelida; filho de Peleu, epít. de Aquiles. 〈Πηλεύς〉</p></section></article>\n<article id=\"entry-dgp-32831\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πήλειος,</h1><div class=\"entry-meta\"><span>DGP · ordem 2513 na letra π · nº geral 32831</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. Πηλήιος, ου (masc.) = Πηλείδης.</p></section></article>\n<article id=\"entry-dgp-32832\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηλείων, ωνος</h1><div class=\"entry-meta\"><span>DGP · ordem 2514 na letra π · nº geral 32832</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) = Πηλεΐδης.</p></section></article>\n<article id=\"entry-dgp-32833\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηλείωναδε</h1><div class=\"entry-meta\"><span>DGP · ordem 2515 na letra π · nº geral 32833</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em direção ao filho de Peleu. 〈Πη­λείων, -δε〉</p></section></article>\n<article id=\"entry-dgp-32834\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηλεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2516 na letra π · nº geral 32834</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Peleu, filho de Éaco, marido de Tétis e pai de Aquiles.</p></section></article>\n<article id=\"entry-dgp-32835\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηληϊάδης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 2517 na letra π · nº geral 32835</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) jôn. = Πηλεΐδης.</p></section></article>\n<article id=\"entry-dgp-32836\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήληξ, ῆκος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2518 na letra π · nº geral 32836</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">elmo; elmo com penacho flutuante. 〈πάλλω〉</p></section></article>\n<article id=\"entry-dgp-32837\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηλιάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2519 na letra π · nº geral 32837</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) dο Pélion. 〈Πήλιον〉</p></section></article>\n<article id=\"entry-dgp-32838\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηλίκος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2520 na letra π · nº geral 32838</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pron. 1 inter. quão grande? de que tamanho? 2 indef. de um certo tamanho; de uma certa idade.</p></section></article>\n<article id=\"entry-dgp-32839\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήλινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2521 na letra π · nº geral 32839</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de argila 2 feito com mistura de argila e palha tratada ♦ οἱ πήλινοι 3 estatuinhas de argila. 〈πηλός〉</p></section></article>\n<article id=\"entry-dgp-32840\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πήλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2522 na letra π · nº geral 32840</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pélion, monte da Tessália.</p></section></article>\n<article id=\"entry-dgp-32841\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηλιῶτις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2523 na letra π · nº geral 32841</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) do Pélion. 〈Πήλιον〉</p></section></article>\n<article id=\"entry-dgp-32842\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηλοπλάθος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2524 na letra π · nº geral 32842</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">modelador de argila; escultor de estátuas de terracota; oleiro. 〈πηλός, πλάσσω〉</p></section></article>\n<article id=\"entry-dgp-32843\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηλός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2525 na letra π · nº geral 32843</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lama; lodo 2 charco 3 argila 4 morteiro feito de argila misturada com palha. 〈πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-32844\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηλουργός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2526 na letra π · nº geral 32844</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">oleiro; ceramista. 〈πηλός, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-32845\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηλούσιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2527 na letra π · nº geral 32845</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Pelúsio, cidade do Egito na foz do Nilo.</p></section></article>\n<article id=\"entry-dgp-32846\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηλούσιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2528 na letra π · nº geral 32846</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Pelúsiο. 〈Πηλούσιον〉</p></section></article>\n<article id=\"entry-dgp-32847\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηλουσιώτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 2529 na letra π · nº geral 32847</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) habitante de Pelúsio. 〈Πηλού­σιον〉</p></section></article>\n<article id=\"entry-dgp-32848\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηλόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2530 na letra π · nº geral 32848</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cobrir de lama ♦ pas. 2 cobrir-se ou sujar-se lama. 〈πηλός〉</p></section></article>\n<article id=\"entry-dgp-32849\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηλώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 2531 na letra π · nº geral 32849</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lamacento; lodoso. 〈πηλός, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-32850\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήλωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2532 na letra π · nº geral 32850</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de chafurdar-se na lama. 〈πηλόω〉</p></section></article>\n<article id=\"entry-dgp-32851\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῆμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2533 na letra π · nº geral 32851</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sofrimento; mal; desgraça 2 flagelo; calamidade. 〈πάσχω〉</p></section></article>\n<article id=\"entry-dgp-32852\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πημαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2534 na letra π · nº geral 32852</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐπήμαινον, fut. πημανῶ, aor. ἐπήμηνα, perf. desus.; pas. aor. ἐπημάνθην, perf. desus.) 1 causar dano a; prejudicar; danificar alguém ou algo, ac., com algo, dat., em algo, ac. 2 danificar algo, ac.: π. τὴν γῆν her. devastar o país 3 passar por cima de; desrespeitar; violar, ὑπέρ e ac.: π. ὑπὲρ ὅρκια hom. violar os juramentos ♦ méd. 4 intr. sofrer as consequências de dano causado a outrem; prejudicar-se a si mesmo; arrepender-se ♦ pas. 5 ser lesado; ser prejudicado. 〈πῆμα〉</p></section></article>\n<article id=\"entry-dgp-32853\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πημονή, ῆς (ἡ) 1 = πῆμα</h1><div class=\"entry-meta\"><span>DGP · ordem 2535 na letra π · nº geral 32853</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2 propósito hostil.</p></section></article>\n<article id=\"entry-dgp-32854\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πημοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2536 na letra π · nº geral 32854</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πημονή.</p></section></article>\n<article id=\"entry-dgp-32855\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηνειός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2537 na letra π · nº geral 32855</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Peneu, rio da Tessália.</p></section></article>\n<article id=\"entry-dgp-32856\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πηνελόπεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2538 na letra π · nº geral 32856</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Penélope, esposa de Odisseu.</p></section></article>\n<article id=\"entry-dgp-32857\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2539 na letra π · nº geral 32857</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fio de tecelagem 2 trama; tecido; tela.</p></section></article>\n<article id=\"entry-dgp-32858\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηνίκα</h1><div class=\"entry-meta\"><span>DGP · ordem 2540 na letra π · nº geral 32858</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. inter. 1 a que horas?: πηνίκα ἐστὶ τῆς ἡμέ­ρας; ar. que horas são? πηνίκα μάλιστα; plat. que horas são no máximo? 2 tard. quando? em que época? 〈ἡνίκα〉</p></section></article>\n<article id=\"entry-dgp-32859\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηνίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2541 na letra π · nº geral 32859</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fio enrolado no lançadeira 2 lançadeira com fio enrolado 3 trama; tecido; tela. 〈πήνη〉</p></section></article>\n<article id=\"entry-dgp-32860\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήνισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2542 na letra π · nº geral 32860</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">trama; tecido. 〈πήνη〉</p></section></article>\n<article id=\"entry-dgp-32861\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηνῖτις, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2543 na letra π · nº geral 32861</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tecelã, epít. de Atena.</p></section></article>\n<article id=\"entry-dgp-32862\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήξασθαι</h1><div class=\"entry-meta\"><span>DGP · ordem 2544 na letra π · nº geral 32862</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. méd. de πήγνυμι.</p></section></article>\n<article id=\"entry-dgp-32863\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2545 na letra π · nº geral 32863</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">parente por vínculo de casamento; parente por afinidade. 〈πάομαι〉</p></section></article>\n<article id=\"entry-dgp-32864\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2546 na letra π · nº geral 32864</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mochila; bolsa de couro; alforje; bolsa.</p></section></article>\n<article id=\"entry-dgp-32865\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήρη</h1><div class=\"entry-meta\"><span>DGP · ordem 2547 na letra π · nº geral 32865</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = πήρα.</p></section></article>\n<article id=\"entry-dgp-32866\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2548 na letra π · nº geral 32866</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 privado do uso de um membro; mutilado; estropiado; manco 2 cego 3 embotado (espírito); tolo. 〈παίω〉</p></section></article>\n<article id=\"entry-dgp-32867\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηρόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2549 na letra π · nº geral 32867</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 privar do uso de um ou de vários membros; estropiar; mutilar 2 castrar 3 embotar; tornar ineficaz. 〈πηρός〉</p></section></article>\n<article id=\"entry-dgp-32868\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήρωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2550 na letra π · nº geral 32868</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 privação do uso de um membro; mutilação 2 cegueira 3 privação da inteligência; debilidade. 〈πηρόω〉</p></section></article>\n<article id=\"entry-dgp-32869\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηχυαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2551 na letra π · nº geral 32869</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">do tamanho de um côvado em largura ou em extensão. 〈πήχυς〉</p></section></article>\n<article id=\"entry-dgp-32870\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήχυς, εως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2552 na letra π · nº geral 32870</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cotovelo 2 côvado, medida de comprimento equiv. a aprox. 44 cm. 3 régua ou esquadro de um côvado 4 ângulo 5 curvatura do arco 6 antebraço 7 pl. peças ou braços de lira unidos por uma barra transversal 8 braço de balança 9 pl. representações pictóricas de homens do tamanho de um côvado, i.e, de pigmeus ao redor do Nilo.</p></section></article>\n<article id=\"entry-dgp-32871\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2553 na letra π · nº geral 32871</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. e tard. = πιέζω.</p></section></article>\n<article id=\"entry-dgp-32872\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 2554 na letra π · nº geral 32872</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. πιανῶ, aor. ἐπίανα, perf. desus.; pas. aor. ἐπιάνθην, perf. πεπίασμαι) 1 fazer engordar; tornar gordo 2 fazer crescer; aumentar: πλοῦτον πιαίνων pínd. fazendo aumentar a riqueza 3 adubar; fecundar (terra) 4 tornar opulento, importante (lugar) 5 inflar o ânimo de; alimentar alguém (com ilusões), ac. 6 alegrar alguém ♦ méd. 7 alegrar-se com, dat. ou part. ♦ pas. 8 tornar-se gordo 9 ficar cheio. 〈πίων〉</p></section></article>\n<article id=\"entry-dgp-32873\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῖαρ</h1><div class=\"entry-meta\"><span>DGP · ordem 2555 na letra π · nº geral 32873</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só nom. e ac. sing. (τό) 1 gordura 2 sumo gorduroso (de fruto, de árvore) 3 sumo 4 creme 5 fertilidade.</p></section></article>\n<article id=\"entry-dgp-32874\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίασμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 2556 na letra π · nº geral 32874</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquilo que fertiliza; fertilizante, ref. a rio. 〈πιαίνω〉</p></section></article>\n<article id=\"entry-dgp-32875\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2557 na letra π · nº geral 32875</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de adubar; adubação. 〈πιαίνω〉</p></section></article>\n<article id=\"entry-dgp-32876\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιδακώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 2558 na letra π · nº geral 32876</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rico de fontes. 〈πῖδαξ, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-32877\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῖδαξ, ακος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2559 na letra π · nº geral 32877</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fonte 2 água de fonte.</p></section></article>\n<article id=\"entry-dgp-32878\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιδήεις, ήεσσα, ῆεν</h1><div class=\"entry-meta\"><span>DGP · ordem 2560 na letra π · nº geral 32878</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">πιδακώδης.</p></section></article>\n<article id=\"entry-dgp-32879\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιδύω</h1><div class=\"entry-meta\"><span>DGP · ordem 2561 na letra π · nº geral 32879</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) at. e méd. brotar; jorrar.</p></section></article>\n<article id=\"entry-dgp-32880\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίε</h1><div class=\"entry-meta\"><span>DGP · ordem 2562 na letra π · nº geral 32880</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">2ª sing. imper. aor.2 poét., πιέειν inf. aor.2 poét., de πίνω.</p></section></article>\n<article id=\"entry-dgp-32881\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιεζέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2563 na letra π · nº geral 32881</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ép. πιέζευν) = πιέζω.</p></section></article>\n<article id=\"entry-dgp-32882\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιέζω</h1><div class=\"entry-meta\"><span>DGP · ordem 2564 na letra π · nº geral 32882</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. πιέσω, aor. ἐπίεσα e ἐπίασα, perf. desus.; pas. aor. ἐπιέσθην, perf. πεπίεσμαι) 1 apertar; comprimir; estreitar: χειρὶ ἐπίεζε βραχίονα hom. estreitava com a mão o braço, πόδα χειρὶ πιέζῃς hes. apertas com a mão o pé 2 prender; segurar: τινὰ ἐν δεσμοῖσι πιέζειν hom. prender, apertar alguém em laços, ἐζήτουν οὖν αὐτὸν πιάσαι n.t. procuravam então prendê-lo 3 acuar; encurralar 4 atormentar; arruinar; oprimir: τινὰ λιμῷ π. xen. submeter, reduzir alguém à fome 5 levar alguém à parede; derrotar numa controvérsia; refutar 6 pressionar; insistir em; tomar em especial consideração 7 reprimir (cólera) ♦ pas. 8 ser pressionado; ser curvado; curvar-se sob o peso de algo 9 ser oprimido, abatido por, dat. ou ὑπό e gen. ou dat. 10 intr. cair na miséria; passar fome, necessidade.</p></section></article>\n<article id=\"entry-dgp-32883\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιεῖν</h1><div class=\"entry-meta\"><span>DGP · ordem 2565 na letra π · nº geral 32883</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 de πίνω.</p></section></article>\n<article id=\"entry-dgp-32884\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίειρα, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 2566 na letra π · nº geral 32884</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) = πίων.</p></section></article>\n<article id=\"entry-dgp-32885\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιέμεν</h1><div class=\"entry-meta\"><span>DGP · ordem 2567 na letra π · nº geral 32885</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor.2 ép. de πίνω.</p></section></article>\n<article id=\"entry-dgp-32886\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πίερες, ων (οἱ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2568 na letra π · nº geral 32886</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitantes da Piéria. 〈Πιερία〉</p></section></article>\n<article id=\"entry-dgp-32887\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πιερία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2569 na letra π · nº geral 32887</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Piéria, região da Macedônia, perto do monte Olimpo.</p></section></article>\n<article id=\"entry-dgp-32888\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πιερικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2570 na letra π · nº geral 32888</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Piéria. 〈Πιερία〉</p></section></article>\n<article id=\"entry-dgp-32889\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πιερίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 2571 na letra π · nº geral 32889</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 da Piéria ♦ ἡ Πιερίς 2 a Musa 3 pl. as Musas. 〈Πιερία〉</p></section></article>\n<article id=\"entry-dgp-32890\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθάκνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2572 na letra π · nº geral 32890</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequeno barril (para secos e molhados) 2 barril 3 Medic. frasco; recipiente (de farmácia). 〈πίθος〉</p></section></article>\n<article id=\"entry-dgp-32891\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίθακος</h1><div class=\"entry-meta\"><span>DGP · ordem 2573 na letra π · nº geral 32891</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = πίθηκος.</p></section></article>\n<article id=\"entry-dgp-32892\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθανολογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2574 na letra π · nº geral 32892</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">falar de modo persuasivo; empregar argumentos plausíveis. 〈πιθανολόγος〉</p></section></article>\n<article id=\"entry-dgp-32893\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθανολογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2575 na letra π · nº geral 32893</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fala persuasiva; argumento plausível. 〈πιθανολόγος〉</p></section></article>\n<article id=\"entry-dgp-32894\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθανολόγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 2576 na letra π · nº geral 32894</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">persuasivo. 〈πιθανός, λέγω〉</p></section></article>\n<article id=\"entry-dgp-32895\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθανός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 2577 na letra π · nº geral 32895</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 capaz de persuadir; persuasivo (pessoa); que inspira confiança; que tem crédito junto de alguém, dat.; que persuade a algo, εἰς e ac. ou inf. 2 que sabe persuadir a seu favor; que predispõe favoravelmente; que agrada (caráter) 3 plausível; crível (coisa) 4 convincente pela semelhança; semelhante ao verdadeiro, ao vivo; verossímil (obra de arte) 5 fácil de crer; crédulo 6 que se deixa convencer; ingênuo; obediente; dócil ♦ τό πιθανόν 7 coisa crível, verossímil. 〈πείθω〉</p></section></article>\n<article id=\"entry-dgp-32896\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθανότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2578 na letra π · nº geral 32896</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 capacidade para persuadir ou para agradar 2 credibilidade; crédito 3 capacidade de atrair; fascínio 4 verossimilhança. 〈πιθανός〉</p></section></article>\n<article id=\"entry-dgp-32897\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθανόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 2579 na letra π · nº geral 32897</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tornar verossímil. 〈πιθανός〉</p></section></article>\n<article id=\"entry-dgp-32898\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθανῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 2580 na letra π · nº geral 32898</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. de modo persuasivo ou plausível; de modo verossímil.</p></section></article>\n<article id=\"entry-dgp-32899\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθηκιδεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2581 na letra π · nº geral 32899</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filhote de macaco; macaquinho. 〈πίθηκος〉</p></section></article>\n<article id=\"entry-dgp-32900\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθηκισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 2582 na letra π · nº geral 32900</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 macaquice 2 adulação; malícia. 〈πί­θηκος〉</p></section></article>\n";
